<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue';

const props = defineProps({ mode: String, indexUrl: String, createUrl: String, storeUrl: String, updateUrl: String, csrf: String, banner: String, errors: String, old: String });
const safeJson = (value, fallback = {}) => { try { return value ? JSON.parse(value) : fallback; } catch { return fallback; } };
const rowState = reactive({ banners: [], pagination: {}, search: '', status: '' });
const loading = ref(true); const failure = ref(''); const preview = ref(props.mode === 'edit' ? safeJson(props.banner).image_url : ''); const selectedImage = ref(null);
const existing = safeJson(props.banner); const oldValues = safeJson(props.old);
const errors = safeJson(props.errors);
const form = reactive({ title: oldValues.title ?? existing.title ?? '', subtitle: oldValues.subtitle ?? existing.subtitle ?? '', button_text: oldValues.button_text ?? existing.button_text ?? '', button_url: oldValues.button_url ?? existing.button_url ?? '', position: oldValues.position ?? existing.position ?? 0, status: oldValues.status ?? existing.status ?? 'active', start_date: oldValues.start_date ?? existing.start_date ?? '', end_date: oldValues.end_date ?? existing.end_date ?? '' });
const heading = computed(() => props.mode === 'edit' ? 'Edit Banner' : 'Create Banner');
let searchTimer;
const request = async (url, options = {}) => { const response = await fetch(url, { credentials: 'same-origin', ...options, headers: { Accept: 'application/json', 'X-Requested-With': 'XMLHttpRequest', ...(options.headers || {}) } }); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.message || `Request failed (${response.status})`); return data; };
async function load(url = window.location.href, push = false) { loading.value = true; failure.value = ''; try { const data = await request(url); rowState.banners = data.banners || []; rowState.pagination = data.pagination || {}; rowState.search = data.search || ''; rowState.status = data.status || ''; if (push) history.pushState({}, '', url); } catch (e) { failure.value = e.message; } finally { loading.value = false; } }
function filteredUrl() { const u = new URL(props.indexUrl, location.origin); if (rowState.search.trim()) u.searchParams.set('search', rowState.search.trim()); if (rowState.status) u.searchParams.set('status', rowState.status); return u.href; }
function applyFilter(push = true) { load(filteredUrl(), push); }
function chooseFile(event) { const file = event.target.files?.[0]; selectedImage.value = file || null; if (preview.value?.startsWith('blob:')) URL.revokeObjectURL(preview.value); if (file && file.type.startsWith('image/')) preview.value = URL.createObjectURL(file); else preview.value = props.mode === 'edit' ? existing.image_url : ''; }
async function removeBanner(row) { if (window.Swal) { const result = await window.Swal.fire({ title: 'Delete banner?', text: `“${row.title}” will be permanently removed.`, icon: 'warning', showCancelButton: true, confirmButtonText: 'Delete', cancelButtonText: 'Cancel' }); if (!result.isConfirmed) return; } else if (!window.confirm(`Delete “${row.title}”?`)) return; try { await request(row.delete_url, { method: 'DELETE', headers: { 'X-CSRF-TOKEN': props.csrf } }); if (window.Swal) window.Swal.fire({ toast: true, position: 'top-end', icon: 'success', title: 'Banner deleted successfully.', showConfirmButton: false, timer: 2200 }); await load(); } catch (e) { failure.value = e.message; } }
function goPage(link) { if (link.url) load(link.url, true); }
function onPop() { load(location.href); }
onMounted(() => { if (props.mode === 'index') load(props.indexUrl + location.search); window.addEventListener('popstate', onPop); if (props.mode === 'index' && location.search) { const params = new URLSearchParams(location.search); rowState.search = params.get('search') || ''; rowState.status = params.get('status') || ''; } });
onBeforeUnmount(() => { window.removeEventListener('popstate', onPop); clearTimeout(searchTimer); if (preview.value?.startsWith('blob:')) URL.revokeObjectURL(preview.value); });
</script>

<template>
    <template v-if="mode==='index'">
        <div class="dashboard-panel mb-4"><div class="panel-header mb-0"><div><h5 class="mb-1">Banners</h5><p class="text-muted mb-0 small">Manage your website banners</p></div><a :href="createUrl" class="btn btn-primary"><i class="bi bi-plus-lg"></i> Add Banner</a></div></div>
        <div class="dashboard-panel mb-4"><form class="banner-filters" @submit.prevent="applyFilter()"><div class="banner-search-group"><input v-model="rowState.search" type="text" class="form-control" placeholder="Search banner..." @input="clearTimeout(searchTimer); searchTimer=setTimeout(()=>applyFilter(),350)"><button type="submit" class="btn btn-primary"><i class="bi bi-search"></i><span>Search</span></button></div><div class="banner-status-filter"><select v-model="rowState.status" class="form-select" @change="applyFilter()"><option value="">All Statuses</option><option value="active">Active</option><option value="inactive">Inactive</option></select></div><a v-if="rowState.search || rowState.status" :href="indexUrl" class="btn btn-light banner-reset-btn" @click.prevent="rowState.search='';rowState.status='';applyFilter()"><i class="bi bi-arrow-counterclockwise"></i> Reset</a></form></div>
        <div v-if="failure" class="alert alert-danger" role="alert">{{ failure }} <button class="btn btn-sm btn-light ms-2" @click="load()">Retry</button></div>
        <div id="banners-results"><div class="dashboard-panel"><div class="table-responsive"><table class="table banners-table align-middle mb-0"><thead><tr><th width="60">#</th><th width="120">Image</th><th>Title</th><th>Position</th><th>Status</th><th>Dates</th><th width="130" class="text-end">Actions</th></tr></thead><tbody>
            <tr v-if="loading"><td colspan="7" class="text-center py-4">Loading banners…</td></tr>
            <tr v-for="(banner,index) in rowState.banners" v-else :key="banner.id"><td>{{ (rowState.pagination.first_item || 1)+index }}</td><td><div class="banner-image-wrapper"><img v-if="banner.image_url" :src="banner.image_url" :alt="banner.title" class="banner-image"><span v-else class="text-muted">—</span></div></td><td><div class="banner-title">{{ banner.title }}</div><div v-if="banner.subtitle" class="banner-subtitle">{{ banner.subtitle }}</div></td><td><span class="position-badge">{{ banner.position }}</span></td><td><span class="status-badge" :class="banner.status==='active'?'status-active':'status-inactive'"><span class="status-dot"></span>{{ banner.status==='active'?'Active':'Inactive' }}</span></td><td><div v-if="banner.start_date || banner.end_date" class="banner-dates"><div v-if="banner.start_date"><i class="bi bi-calendar-event"></i> {{ banner.start_date }}</div><div v-if="banner.end_date"><i class="bi bi-calendar-check"></i> {{ banner.end_date }}</div></div><span v-else class="text-muted">No date limit</span></td><td><div class="banner-actions"><a :href="banner.edit_url" class="action-btn action-edit" title="Edit"><i class="bi bi-pencil"></i></a><button type="button" class="action-btn action-delete" title="Delete" @click="removeBanner(banner)"><i class="bi bi-trash"></i></button></div></td></tr>
            <tr v-if="!loading && !rowState.banners.length"><td colspan="7"><div class="empty-state"><div class="empty-icon"><i class="bi bi-image"></i></div><h6>No banners found</h6><p>Create your first banner to display it on your website.</p><a :href="createUrl" class="btn btn-primary"><i class="bi bi-plus-lg"></i> Add Banner</a></div></td></tr>
        </tbody></table></div><div v-if="rowState.pagination.total" class="banners-pagination"><div class="banners-pagination-info">Showing <strong>{{ rowState.pagination.first_item || 0 }}</strong> to <strong>{{ rowState.pagination.last_item || 0 }}</strong> of <strong>{{ rowState.pagination.total }}</strong> results</div><div class="banners-pagination-links"><button v-for="(link,i) in rowState.pagination.links || []" :key="i" type="button" class="banner-page-btn" :class="{active:link.active,disabled:!link.url}" :disabled="!link.url" @click="goPage(link)">{{ link.label.replace('&laquo;','‹').replace('&raquo;','›') }}</button></div></div></div></div>
    </template>
    <template v-else>
        <div class="dashboard-panel mb-4"><div class="panel-header mb-0"><div><h5 class="mb-1">{{ heading }}</h5><p class="text-muted mb-0 small">{{ mode==='edit'?'Update your website banner':'Add a new banner to your website' }}</p></div><a :href="indexUrl" class="btn btn-light banner-back-btn"><i class="bi bi-arrow-left"></i> Back to Banners</a></div></div>
        <div v-if="Object.keys(errors).length" class="alert alert-danger mb-4"><div class="fw-semibold mb-2">Please fix the following errors:</div><ul class="mb-0 ps-3"><li v-for="(messages,key) in errors" :key="key">{{ messages[0] }}</li></ul></div>
        <form :action="mode==='edit'?updateUrl:storeUrl" method="POST" enctype="multipart/form-data"><input type="hidden" name="_token" :value="csrf"><input v-if="mode==='edit'" type="hidden" name="_method" value="PUT"><div class="row g-4"><div class="col-lg-8"><div class="dashboard-panel banner-form-panel"><div class="banner-form-heading"><h6>Banner Information</h6><p>Enter the content that will be displayed on the banner.</p></div><div class="mb-4"><label for="title" class="form-label">Title <span class="text-danger">*</span></label><input id="title" v-model="form.title" name="title" class="form-control" placeholder="Enter banner title" maxlength="255" required><div v-if="errors.title" class="invalid-feedback d-block">{{ errors.title[0] }}</div></div><div class="mb-4"><label for="subtitle" class="form-label">Subtitle</label><input id="subtitle" v-model="form.subtitle" name="subtitle" class="form-control" placeholder="Enter banner subtitle" maxlength="255"><div v-if="errors.subtitle" class="invalid-feedback d-block">{{ errors.subtitle[0] }}</div></div><div class="row g-3"><div class="col-md-6"><label for="button_text" class="form-label">Button Text</label><input id="button_text" v-model="form.button_text" name="button_text" class="form-control" placeholder="e.g. Shop Now" maxlength="100"><div v-if="errors.button_text" class="invalid-feedback d-block">{{ errors.button_text[0] }}</div></div><div class="col-md-6"><label for="button_url" class="form-label">Button URL</label><input id="button_url" v-model="form.button_url" name="button_url" class="form-control" placeholder="e.g. /books" maxlength="500"><div v-if="errors.button_url" class="invalid-feedback d-block">{{ errors.button_url[0] }}</div></div></div></div></div>
            <div class="col-lg-4"><div class="dashboard-panel banner-form-panel"><div class="banner-form-heading"><h6>Banner Settings</h6><p>Configure position and visibility.</p></div><div class="mb-4"><label for="position" class="form-label">Position <span class="text-danger">*</span></label><input id="position" v-model="form.position" type="number" name="position" min="0" class="form-control" required><div class="form-text">Lower numbers are displayed first.</div><div v-if="errors.position" class="invalid-feedback d-block">{{ errors.position[0] }}</div></div><div class="mb-4"><label for="status" class="form-label">Status <span class="text-danger">*</span></label><select id="status" v-model="form.status" name="status" class="form-select" required><option value="active">Active</option><option value="inactive">Inactive</option></select><div v-if="errors.status" class="invalid-feedback d-block">{{ errors.status[0] }}</div></div><div class="mb-4"><label for="start_date" class="form-label">Start Date</label><input id="start_date" v-model="form.start_date" type="date" name="start_date" class="form-control"><div v-if="errors.start_date" class="invalid-feedback d-block">{{ errors.start_date[0] }}</div></div><div><label for="end_date" class="form-label">End Date</label><input id="end_date" v-model="form.end_date" type="date" name="end_date" class="form-control"><div v-if="errors.end_date" class="invalid-feedback d-block">{{ errors.end_date[0] }}</div></div></div></div>
            <div class="col-12"><div class="dashboard-panel banner-form-panel"><div class="banner-form-heading"><h6>Banner Image</h6><p>{{ mode==='edit'?'Upload a new image if you want to replace the current one.':'Upload the image that will be displayed on the website.' }}</p></div><div class="banner-upload-area"><div class="banner-preview-wrapper"><div v-if="!preview" class="banner-preview-placeholder"><i class="bi bi-image"></i><span>Image Preview</span></div><img v-else class="banner-preview-image" :src="preview" alt="Banner Preview"></div><div class="banner-upload-content"><label for="image" class="form-label">{{ mode==='edit'?'Replace Banner Image':'Banner Image' }}<span v-if="mode==='create'" class="text-danger"> *</span></label><input id="image" type="file" name="image" accept=".jpg,.jpeg,.png,.webp" class="form-control" :required="mode==='create'" @change="chooseFile"><div class="form-text">{{ mode==='edit'?'Leave empty to keep the current image. ':'' }}JPG, JPEG, PNG or WEBP. Maximum size: 2MB.</div><div v-if="errors.image" class="invalid-feedback d-block">{{ errors.image[0] }}</div></div></div></div></div></div><div class="banner-form-actions"><a :href="indexUrl" class="btn btn-light banner-cancel-btn">Cancel</a><button type="submit" class="btn btn-primary"><i class="bi bi-check-lg"></i> {{ mode==='edit'?'Update Banner':'Create Banner' }}</button></div></form>
    </template>
</template>
